fn frame(t: i32) {
    let w: i32 = host::display::width();
    let h: i32 = host::display::height();
    if host::display::state_get(0) == 0 {
        host::display::state_set(0, 1);
        let mut k: i32 = 0;
        while k < 8 {
            host::display::state_set(10 + k * 2, w / 2);
            host::display::state_set(11 + k * 2, h / 2);
            k = k + 1;
        }
    }
    let mut tx: i32 = host::display::pointer_x();
    let mut ty: i32 = host::display::pointer_y();
    host::display::clear(0x000000);
    let mut i: i32 = 0;
    while i < 8 {
        let mut x: i32 = host::display::state_get(10 + i * 2);
        let mut y: i32 = host::display::state_get(11 + i * 2);
        x = x + (tx - x) / 6;
        y = y + (ty - y) / 6;
        host::display::state_set(10 + i * 2, x);
        host::display::state_set(11 + i * 2, y);
        let size: i32 = 16 - i * 2;
        let g: i32 = 255 - i * 24;
        host::display::fill_rect(x - size / 2, y - size / 2, size, size, g * 256 + g / 3);
        tx = x;
        ty = y;
        i = i + 1;
    }
    host::display::present();
}
